import React, { useState, useEffect } from 'react';
import { useBot } from '../contexts/BotContext';

const FileManager = () => {
  const { botState } = useBot();
  const [files, setFiles] = useState([]);
  const [selectedFile, setSelectedFile] = useState(null);
  const [uploadProgress, setUploadProgress] = useState(0);
  const [isUploading, setIsUploading] = useState(false);
  const [uploadTarget, setUploadTarget] = useState('');
  const [uploadCredentials, setUploadCredentials] = useState({
    username: '',
    password: '',
    website: ''
  });
  const [uploadHistory, setUploadHistory] = useState([]);

  useEffect(() => {
    // Load actual files from the bot's file system
    loadFiles();
    loadUploadHistory();
  }, []);

  const loadFiles = async () => {
    try {
      // Call Python backend to get actual files
      const response = await fetch('/api/files', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        }
      });
      
      if (response.ok) {
        const fileData = await response.json();
        setFiles(fileData.files || []);
      } else {
        console.error('Failed to load files');
        // Fallback to mock data for development
        setFiles([
          { id: 1, name: 'config.json', size: '2.1 KB', type: 'JSON', lastModified: '2024-01-15', path: '/config/config.json' },
          { id: 2, name: 'bot_log.txt', size: '15.7 KB', type: 'TXT', lastModified: '2024-01-15', path: '/logs/bot_log.txt' },
          { id: 3, name: 'data_processor.py', size: '8.3 KB', type: 'Python', lastModified: '2024-01-14', path: '/src/data_processor.py' },
          { id: 4, name: 'main_bot.py', size: '12.1 KB', type: 'Python', lastModified: '2024-01-14', path: '/src/main_bot.py' },
        ]);
      }
    } catch (error) {
      console.error('Error loading files:', error);
    }
  };

  const loadUploadHistory = async () => {
    try {
      const response = await fetch('/api/upload-history', {
        method: 'GET',
        headers: {
          'Content-Type': 'application/json',
        }
      });
      
      if (response.ok) {
        const history = await response.json();
        setUploadHistory(history.uploads || []);
      }
    } catch (error) {
      console.error('Error loading upload history:', error);
    }
  };

  const handleFileUpload = async (event) => {
    const file = event.target.files[0];
    if (!file) return;

    if (!uploadTarget || !uploadCredentials.website) {
      alert('กรุณาระบุเว็บไซต์เป้าหมายและข้อมูลการเข้าสู่ระบบ');
      return;
    }

    setIsUploading(true);
    setUploadProgress(0);

    try {
      // Create FormData for file upload
      const formData = new FormData();
      formData.append('file', file);
      formData.append('target_website', uploadTarget);
      formData.append('username', uploadCredentials.username);
      formData.append('password', uploadCredentials.password);
      formData.append('upload_path', uploadTarget);

      // Simulate progress updates
      const progressInterval = setInterval(() => {
        setUploadProgress(prev => {
          if (prev >= 90) {
            clearInterval(progressInterval);
            return 90;
          }
          return prev + 10;
        });
      }, 200);

      // Send file to Python backend for web upload
      const response = await fetch('/api/upload-to-web', {
        method: 'POST',
        body: formData
      });

      clearInterval(progressInterval);
      setUploadProgress(100);

      if (response.ok) {
        const result = await response.json();
        
        // Add to upload history
        const newUpload = {
          id: Date.now(),
          filename: file.name,
          target: uploadTarget,
          status: 'success',
          timestamp: new Date().toISOString(),
          message: result.message || 'อัปโหลดสำเร็จ'
        };
        
        setUploadHistory(prev => [newUpload, ...prev]);
        
        alert(`อัปโหลดไฟล์ ${file.name} ไปยัง ${uploadTarget} สำเร็จ!`);
        
        // Reset form
        setUploadTarget('');
        setUploadCredentials({ username: '', password: '', website: '' });
        
        // Reload files
        await loadFiles();
      } else {
        const error = await response.json();
        throw new Error(error.message || 'การอัปโหลดล้มเหลว');
      }
    } catch (error) {
      console.error('Upload error:', error);
      alert(`ข้อผิดพลาดในการอัปโหลด: ${error.message}`);
      
      // Add failed upload to history
      const failedUpload = {
        id: Date.now(),
        filename: file.name,
        target: uploadTarget,
        status: 'failed',
        timestamp: new Date().toISOString(),
        message: error.message
      };
      
      setUploadHistory(prev => [failedUpload, ...prev]);
    } finally {
      setIsUploading(false);
      setUploadProgress(0);
      // Reset file input
      event.target.value = '';
    }
  };

  const handleFileDelete = async (fileId) => {
    try {
      const response = await fetch(`/api/files/${fileId}`, {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        }
      });

      if (response.ok) {
        setFiles(files.filter(file => file.id !== fileId));
        alert('ลบไฟล์สำเร็จ');
      } else {
        alert('ไม่สามารถลบไฟล์ได้');
      }
    } catch (error) {
      console.error('Delete error:', error);
      alert('เกิดข้อผิดพลาดในการลบไฟล์');
    }
  };

  const handleFileSelect = (file) => {
    setSelectedFile(file);
  };

  const downloadFile = async (file) => {
    try {
      const response = await fetch(`/api/files/${file.id}/download`, {
        method: 'GET',
      });

      if (response.ok) {
        const blob = await response.blob();
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = file.name;
        document.body.appendChild(a);
        a.click();
        window.URL.revokeObjectURL(url);
        document.body.removeChild(a);
      } else {
        alert('ไม่สามารถดาวน์โหลดไฟล์ได้');
      }
    } catch (error) {
      console.error('Download error:', error);
      alert('เกิดข้อผิดพลาดในการดาวน์โหลด');
    }
  };

  const retryUpload = async (upload) => {
    // Implement retry logic for failed uploads
    alert('ฟีเจอร์นี้จะถูกเพิ่มในอนาคต');
  };

  return (
    <div className="p-6">
      <div className="mb-6">
        <h1 className="text-2xl font-bold text-gray-900 mb-2">File Manager</h1>
        <p className="text-gray-600">จัดการไฟล์และอัปโหลดไปยังเว็บไซต์ผ่านบอท</p>
      </div>

      {/* Upload Configuration */}
      <div className="bg-white rounded-lg shadow p-6 mb-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">ตั้งค่าการอัปโหลด</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">เว็บไซต์เป้าหมาย</label>
            <input
              type="text"
              value={uploadCredentials.website}
              onChange={(e) => setUploadCredentials(prev => ({ ...prev, website: e.target.value }))}
              placeholder="https://example.com"
              className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">พาธอัปโหลด</label>
            <input
              type="text"
              value={uploadTarget}
              onChange={(e) => setUploadTarget(e.target.value)}
              placeholder="/upload/ หรือ /files/"
              className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">ชื่อผู้ใช้</label>
            <input
              type="text"
              value={uploadCredentials.username}
              onChange={(e) => setUploadCredentials(prev => ({ ...prev, username: e.target.value }))}
              placeholder="username"
              className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-gray-700 mb-2">รหัสผ่าน</label>
            <input
              type="password"
              value={uploadCredentials.password}
              onChange={(e) => setUploadCredentials(prev => ({ ...prev, password: e.target.value }))}
              placeholder="password"
              className="w-full border border-gray-300 rounded-md px-3 py-2 focus:outline-none focus:ring-2 focus:ring-blue-500"
            />
          </div>
        </div>

        {/* File Upload */}
        <div className="border-2 border-dashed border-gray-300 rounded-lg p-6 text-center">
          <input
            type="file"
            onChange={handleFileUpload}
            className="hidden"
            id="file-upload"
            disabled={isUploading}
          />
          <label
            htmlFor="file-upload"
            className={`cursor-pointer text-blue-600 hover:text-blue-800 font-medium ${
              isUploading ? 'opacity-50 cursor-not-allowed' : ''
            }`}
          >
            {isUploading ? 'กำลังอัปโหลด...' : 'คลิกเพื่อเลือกไฟล์'}
          </label>
          <p className="text-sm text-gray-500 mt-2">
            {isUploading ? 'กรุณารอสักครู่' : 'หรือลากและวางไฟล์ที่นี่'}
          </p>
        </div>

        {/* Upload Progress */}
        {uploadProgress > 0 && (
          <div className="mt-4">
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div
                className="bg-blue-600 h-2 rounded-full transition-all duration-300"
                style={{ width: `${uploadProgress}%` }}
              ></div>
            </div>
            <p className="text-sm text-gray-600 mt-2">
              {isUploading ? 'กำลังอัปโหลดไปยังเว็บไซต์...' : 'อัปโหลดเสร็จสิ้น'} {uploadProgress}%
            </p>
          </div>
        )}
      </div>

      {/* Upload History */}
      <div className="bg-white rounded-lg shadow p-6 mb-6">
        <h2 className="text-lg font-semibold text-gray-900 mb-4">ประวัติการอัปโหลด</h2>
        <div className="max-h-64 overflow-y-auto">
          {uploadHistory.length === 0 ? (
            <p className="text-gray-500 text-center py-4">ยังไม่มีประวัติการอัปโหลด</p>
          ) : (
            <div className="space-y-3">
              {uploadHistory.map((upload) => (
                <div
                  key={upload.id}
                  className={`p-3 rounded-lg border ${
                    upload.status === 'success' 
                      ? 'bg-green-50 border-green-200' 
                      : 'bg-red-50 border-red-200'
                  }`}
                >
                  <div className="flex items-center justify-between">
                    <div>
                      <p className="font-medium text-gray-900">{upload.filename}</p>
                      <p className="text-sm text-gray-600">เป้าหมาย: {upload.target}</p>
                      <p className="text-sm text-gray-500">
                        {new Date(upload.timestamp).toLocaleString()}
                      </p>
                    </div>
                    <div className="flex items-center space-x-2">
                      <span className={`px-2 py-1 rounded-full text-xs font-medium ${
                        upload.status === 'success' 
                          ? 'bg-green-100 text-green-800' 
                          : 'bg-red-100 text-red-800'
                      }`}>
                        {upload.status === 'success' ? 'สำเร็จ' : 'ล้มเหลว'}
                      </span>
                      {upload.status === 'failed' && (
                        <button
                          onClick={() => retryUpload(upload)}
                          className="text-blue-600 hover:text-blue-800 text-sm"
                        >
                          ลองใหม่
                        </button>
                      )}
                    </div>
                  </div>
                  {upload.message && (
                    <p className="text-sm text-gray-600 mt-2">{upload.message}</p>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Files List */}
      <div className="bg-white rounded-lg shadow">
        <div className="px-6 py-4 border-b border-gray-200">
          <h2 className="text-lg font-semibold text-gray-900">ไฟล์ในระบบ</h2>
        </div>
        <div className="divide-y divide-gray-200">
          {files.map((file) => (
            <div
              key={file.id}
              className={`px-6 py-4 hover:bg-gray-50 cursor-pointer ${
                selectedFile?.id === file.id ? 'bg-blue-50' : ''
              }`}
              onClick={() => handleFileSelect(file)}
            >
              <div className="flex items-center justify-between">
                <div className="flex items-center space-x-3">
                  <div className="flex-shrink-0">
                    <div className="w-8 h-8 bg-gray-100 rounded flex items-center justify-center">
                      <span className="text-xs text-gray-600 font-medium">
                        {file.type === 'Python' ? '🐍' : file.type === 'JSON' ? '📄' : '📝'}
                      </span>
                    </div>
                  </div>
                  <div>
                    <p className="text-sm font-medium text-gray-900">{file.name}</p>
                    <p className="text-sm text-gray-500">
                      {file.size} • {file.type} • {file.lastModified}
                    </p>
                    {file.path && (
                      <p className="text-xs text-gray-400 font-mono">{file.path}</p>
                    )}
                  </div>
                </div>
                <div className="flex items-center space-x-2">
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      downloadFile(file);
                    }}
                    className="text-blue-600 hover:text-blue-800 text-sm font-medium"
                  >
                    ดาวน์โหลด
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      handleFileDelete(file.id);
                    }}
                    className="text-red-600 hover:text-red-800 text-sm font-medium"
                  >
                    ลบ
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* File Details */}
      {selectedFile && (
        <div className="mt-6 bg-white rounded-lg shadow p-6">
          <h3 className="text-lg font-semibold text-gray-900 mb-4">รายละเอียดไฟล์</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <p className="text-sm font-medium text-gray-500">ชื่อไฟล์</p>
              <p className="text-sm text-gray-900">{selectedFile.name}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-500">ขนาด</p>
              <p className="text-sm text-gray-900">{selectedFile.size}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-500">ประเภท</p>
              <p className="text-sm text-gray-900">{selectedFile.type}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-gray-500">แก้ไขล่าสุด</p>
              <p className="text-sm text-gray-900">{selectedFile.lastModified}</p>
            </div>
            {selectedFile.path && (
              <div className="col-span-2">
                <p className="text-sm font-medium text-gray-500">พาธ</p>
                <p className="text-sm text-gray-900 font-mono">{selectedFile.path}</p>
              </div>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

export default FileManager;
